private DistancePredicate buildDistancePredicate(double lat, double lon, double radiusMeters) {
  final Rectangle boundingBox = Rectangle.fromPointDistance(lat, lon, radiusMeters);
  final double axisLat = Rectangle.axisLat(lat, radiusMeters);
  final double distanceSortKey = GeoUtils.distanceQuerySortKey(radiusMeters);
  applyGridEncodingPipeline(
      encodeLatitudeCeil(boundingBox.minLat),
      encodeLatitude(boundingBox.maxLat),
      encodeLongitudeCeil(boundingBox.minLon),
      encodeLongitude(boundingBox.maxLon),
      boundingBox.minLon > boundingBox.maxLon);
  final Function<Rectangle, Relation> boxToRelation =
      box ->
          GeoUtils.relate(
              box.minLat, box.maxLat, box.minLon, box.maxLon, lat, lon, distanceSortKey, axisLat);
  final Grid subBoxes =
      createSubBoxes(
          boundingBox.minLat,
          boundingBox.maxLat,
          boundingBox.minLon,
          boundingBox.maxLon,
          boxToRelation);
  return new DistancePredicate(
      subBoxes.latShift,
      subBoxes.lonShift,
      subBoxes.latBase,
      subBoxes.lonBase,
      subBoxes.maxLatDelta,
      subBoxes.maxLonDelta,
      subBoxes.relations,
      lat,
      lon,
      distanceSortKey);
}

private Component2DPredicate buildComponentPredicate(Component2D tree) {
  applyGridEncodingPipeline(
      encodeLatitudeCeil(tree.getMinY()),
      encodeLatitude(tree.getMaxY()),
      encodeLongitudeCeil(tree.getMinX()),
      encodeLongitude(tree.getMaxX()),
      tree.getMinX() > tree.getMaxX());
  final Function<Rectangle, Relation> boxToRelation =
      box -> tree.relate(box.minLon, box.maxLon, box.minLat, box.maxLat);
  final Grid subBoxes =
      createSubBoxes(
          tree.getMinY(), tree.getMaxY(), tree.getMinX(), tree.getMaxX(), boxToRelation);
  return new Component2DPredicate(
      subBoxes.latShift,
      subBoxes.lonShift,
      subBoxes.latBase,
      subBoxes.lonBase,
      subBoxes.maxLatDelta,
      subBoxes.maxLonDelta,
      subBoxes.relations,
      tree);
}
